  "data": {
    "domain": {
      "name": "apple.com",
      "comments": [
        {
          "id": "cmt_12345",
          "text": "Great product!",
          "author": "john_doe",
          "created_at": "2024-05-01T12:34:56Z"
        },
        ...
      ]
    }
  }
}
```

---

